public boolean shouldPrintMessage(int timestamp, String message) {
    // Create a map to store the last printed time for each message
    Map<String, Integer> lastPrintTime = new HashMap<>();

    // If the timestamp is equal to or greater than the lastPrintTime for the message, print the message
