private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int nextByte = bb.get(i);
    if (nextByte < 128) {
        sb.append((char) nextByte);
        return i + 1;
    }

    while (nextByte >= 128) {
        int charValue = (nextByte & 0xf) << 8 | bb.get(i + 1);
        sb.append((char) charValue);
        i += 2;
    }

    return i;
}

private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) throws IllegalArgumentException {
    if (i >= bb.limit()) {
        throw new IllegalArgumentException("position beyond end of buffer");
