public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (row < 0 || row > table.getRowCount() - 1 || table == null || pane == null) {
        throw new IllegalArgumentException("Invalid input parameters.");
    }

    table.getSelectionModel().clearSelection();
    table.getSelectionModel().setSelectedIndex(row);

    // Assuming a delay of 500 milliseconds between selecting the row and repainting
    try {
        Thread.sleep(500);
        pane.repaint();
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
    }
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null || row < 0 || row >= table.getRowCount()) {
        return; // Handle invalid inputs
    }

    table.setRowSelectionInterval(row, row);
    pane.revalidate();
    pane.repaint(); // Repaint the pane after selection
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Both table and JScrollPane cannot be null");
    }

    // Click the row using mouse wheel
    doClick(row, table, pane);

    // Update the scroll pane to the selected row
    int visibleRow = pane.getFirstVisibleRow();
    if (visibleRow >= row) {
        int incrementBy = Math.min(visibleRow, row - visibleRow + 1);
        pane.verticallyScrollBy(incrementBy);
    } else {
        int decrementBy = Math.max(row - visibleRow, 0);
        pane.verticallyScrollBy(-decrementBy);
    }
}

private static void doClick(int row, JTable table, JScrollPane pane) {
    // Simulate mouse click event
    MouseEvent event = new MouseEvent(table, MouseEvent.MOUSE_PRESSED, System.currentTimeMillis(), 0, 0, 20, 0, MouseEvent.LEFT_BUTTON);
    table.dispatchEvent(event);
    MouseEvent releaseEvent = new MouseEvent(table, MouseEvent.MOUSE_RELEASED, System.currentTimeMillis(), 0, 0, 20, 0, MouseEvent.LEFT_BUTTON);
    table.dispatchEvent(releaseEvent);
}

