public void overrideName(String oldName, String newName) {
    // Prevent invalid inputs by checking if the names are null or empty strings
    if (StringUtils.isEmpty(oldName) || StringUtils.isEmpty(newName)) {
        throw new IllegalArgumentException("Name replacement parameters must be non-empty strings.");
    }

    // Find the appropriate field in the class using reflection
    Class<?> clazz = this.getClass();
    Field field = null;
    try {
        field = clazz.getDeclaredField("columnName");
        // Set the field accessible so we can change its value
        field.setAccessible(true);
    } catch (NoSuchFieldException | SecurityException e) {
        throw new RuntimeException("Failed to retrieve field 'columnName', can't implement overrideName method.", e);
    }

    // Retrieve the current column name and replace it with the new name
    String existingName = (String) field.get(this);
    if (!existingName.equals(oldName)) {
        throw new IllegalStateException("The column name to be overridden does not match the one currently in use.");
    }
